//! Native MSVC CRT `_CIpow` (AA.exe `0x96D890`), its SSE2 body
//! (`0x977A10` -> `0x977A29`, 2861 bytes, SHA-256 d9215cd960a6cbd42bca8c7c9751d1bca5880e7ae7f8928ee097129edc979f04) and the
//! observable effects of `___libm_error_support` (`0x977111`).
//!
//! GENERATED by `research/phase8-combat/lift_crt_pow.py` from the original
//! instructions: every basic block of `0x977A29` is a match arm below and
//! every instruction is the binary64 / integer operation it performs under the
//! default MXCSR (`0x1F80`: round to nearest, no FTZ/DAZ). The coefficient
//! tables are the original read-only data `0xAD0BA0..0xAD44C8` (SHA-256
//! e36452f607bdaaf1093d05153d9d4dd96c8b47ed5bd046087bf4bb01ae2b8adb). Do not edit the generated part by hand; regenerate.
//!
//! Verified against the original code in Unicorn by
//! `research/phase8-combat/native_crt_pow.py` (SSE2 is integer/binary64
//! arithmetic, which the emulator computes exactly).
//!
//! * Scalar/packed `addsd/subsd/mulsd/divsd` are evaluated with host binary64
//!   arithmetic for non-NaN results (IEEE 754 round-to-nearest, identical on
//!   every supported host) and with the explicit SSE NaN rules otherwise: the
//!   first NaN operand (destination first) quieted, or the default NaN
//!   `0xFFF8_0000_0000_0000` for an invalid operation. No host NaN payload is
//!   ever observed.
//! * `fld qword` (the return into ST0) quiets a signalling NaN; all x87
//!   exceptions are masked on this path (`_CIpow` requires `CW & 0x7F == 0x7F`).
//! * `_CIpow` stores its x87 operands with `fstp qword`. Callers holding x87
//!   values must round them to binary64 first ([`ci_pow`] then quiets a
//!   signalling NaN as that store does); [`pow_sse2`] is the body itself.
//! * `0x96D890` takes the SSE2 body when the CRT SSE2 flag `[0xB4B340]` is set,
//!   MXCSR masks all exceptions (`& 0x1F80 == 0x1F80`) and the x87 control
//!   word masks all exceptions (`& 0x7F == 0x7F`). Otherwise it runs the x87
//!   body `0x96D8ED`, which is NOT ported: [`ci_pow`] reports it.
#![allow(clippy::all, clippy::pedantic, unused_parens)]

/// `0x96D890` path selection inputs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CrtEnvironment {
    /// CRT SSE2 availability flag `[0xB4B340]` (nonzero on SSE2 CPUs).
    pub sse2_available: bool,
    pub mxcsr: u32,
    pub x87_control: u16,
}

impl CrtEnvironment {
    /// Any SSE2 CPU with the default MXCSR and the simulation control word.
    pub const SSE2_DOUBLE53: Self = Self {
        sse2_available: true,
        mxcsr: 0x1f80,
        x87_control: 0x027f,
    };
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PowPath {
    /// `0x977A10`, ported.
    Sse2,
    /// `0x96D8ED`, not ported.
    X87,
}

/// Native `0x96D890` dispatch.
pub fn select_path(env: CrtEnvironment) -> PowPath {
    if env.sse2_available && env.mxcsr & 0x1f80 == 0x1f80 && env.x87_control & 0x7f == 0x7f {
        PowPath::Sse2
    } else {
        PowPath::X87
    }
}

/// Result of the SSE2 pow body.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PowOutcome {
    /// ST0 on return, exactly a binary64 value (bits).
    pub bits: u64,
    /// `___libm_error_support` code when the native error path ran.
    pub libm_error: Option<u32>,
    /// `errno` value stored by `___libm_error_support`, if any.
    pub errno: Option<u32>,
}
impl PowOutcome {
    pub fn value(self) -> f64 {
        f64::from_bits(self.bits)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
pub enum CrtPowError {
    #[error("_CIpow x87 body 0x96D8ED is not ported")]
    X87PathUnsupported,
    /// The SSE2 body runs, but MXCSR rounding/FTZ/DAZ differ from 0x1F80;
    /// the port models only the default control bits.
    #[error("SSE2 pow under MXCSR {0:#06x} (non-default rounding/FTZ/DAZ) is not modelled")]
    UnsupportedMxcsr(u32),
    #[error("translated SSE2 pow left its modelled state at {0:#x}")]
    Fault(u32),
    /// x87 `fstp qword` of a finite value above the binary64 range (the
    /// native stores an infinity; `Binary` cannot carry it).
    #[error("x87 value overflows binary64")]
    Binary64Overflow,
    /// pow returned an infinity or NaN (bits), outside the `Binary` domain.
    #[error("pow result {0:#018x} is not finite")]
    NonFiniteResult(u64),
}

/// x87 `fstp qword` (round to nearest even; exceptions masked) of a finite
/// register value, including gradual underflow.
pub fn store_binary64(value: &crate::Binary) -> Result<u64, CrtPowError> {
    let sign = u64::from(value.negative) << 63;
    if value.is_zero() {
        return Ok(sign);
    }
    let mut top = value.magnitude.bits() as i32 - 1 + value.exponent;
    let target = (top - 52).max(-1074);
    let mut rounded = if target > value.exponent {
        crate::rounded_shift(&value.magnitude, (target - value.exponent) as u64)
    } else {
        &value.magnitude << (value.exponent - target) as usize
    };
    if top < -1022 {
        // A subnormal rounded up to 2^52 encodes the minimum normal.
        return Ok(sign | u64::try_from(&rounded).expect("binary64 subnormal significand"));
    }
    if rounded.bits() > 53 {
        rounded >>= 1usize;
        top += 1;
    }
    if top > 1023 {
        return Err(CrtPowError::Binary64Overflow);
    }
    let fraction = u64::try_from(&rounded).expect("binary64 significand") & 0x000f_ffff_ffff_ffff;
    Ok(sign | (((top + 1023) as u64) << 52) | fraction)
}

/// `_CIpow` as called from x87 code (`fld x; fld y; call 0x96D890`): the
/// register operands are stored to binary64 and the binary64 ST0 result is
/// returned exactly, with the SSE2 outcome (libm error code, errno).
pub fn ci_pow_x87(
    x: &crate::Binary,
    y: &crate::Binary,
    env: CrtEnvironment,
) -> Result<(crate::Binary, PowOutcome), CrtPowError> {
    let (xb, yb) = (store_binary64(x)?, store_binary64(y)?);
    let out = ci_pow(f(xb), f(yb), env)?;
    let value = crate::Binary::from_f64_bits(out.bits)
        .map_err(|_| CrtPowError::NonFiniteResult(out.bits))?;
    Ok((value, out))
}

/// `_CIpow(x, y)` with the native path selection. `x`/`y` are the binary64
/// values `_CIpow` stores from ST1/ST0.
pub fn ci_pow(x: f64, y: f64, env: CrtEnvironment) -> Result<PowOutcome, CrtPowError> {
    match select_path(env) {
        PowPath::Sse2 if env.mxcsr & 0xffc0 != 0x1f80 => {
            Err(CrtPowError::UnsupportedMxcsr(env.mxcsr))
        }
        // fstp qword of an x87 register never yields a signalling NaN.
        PowPath::Sse2 => pow_sse2_bits(quiet(b(x)), quiet(b(y))),
        PowPath::X87 => Err(CrtPowError::X87PathUnsupported),
    }
}

/// Observable effects of `___libm_error_support(&x, &y, &result, code)`
/// (`0x977111`) with the image's default `_matherr` (`[0xB359A4]` =
/// `0x84D110`, `xor eax,eax; ret`; the pointer is never written by the game).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LibmErrorEffect {
    pub result: u64,
    pub errno: Option<u32>,
}

/// Port of `0x977111` for every code it dispatches (signed compares).
/// `x`/`y`/`result` are the binary64 bits behind its pointer arguments.
/// Copies through x87 `fld/fstp qword` quiet a signalling NaN.
pub fn libm_error_support(x: u64, y: u64, result: u64, code: i32) -> LibmErrorEffect {
    let _ = y;
    // Paths: Copy = *result = *x first; then exception with errno.
    enum Path {
        None,
        One,
        Range,
        Domain { copy_x: bool },
        Silent,
    }
    let path = match code {
        // > 0xA1
        0x3ea | 1000 | 0x3e9 | 0x3eb | 0x3ec | 0x3ed | 0x3ef => Path::Domain { copy_x: true },
        0x3ee | 0xab => Path::Domain { copy_x: false },
        0xa2 | 0xa6 | 0xaa => Path::Range,
        0xa1 => Path::Range,
        // < 0x19
        0x18 | 2 | 8 | 0xe => Path::Range,
        3 | 9 => Path::Domain { copy_x: false },
        0xf => Path::Silent,
        // 0x19..=0xA0
        0x19 => Path::Silent,
        0x1a => Path::One,
        0x1b => Path::Range,
        0x1c => Path::Domain { copy_x: false },
        0x1d => Path::Domain { copy_x: true },
        _ => Path::None,
    };
    match path {
        Path::None => LibmErrorEffect {
            result,
            errno: None,
        },
        Path::One => LibmErrorEffect {
            result: 0x3ff0_0000_0000_0000,
            errno: None,
        },
        // _matherr(&exc) returns 0 -> errno; *result = exc.retval.
        Path::Range => LibmErrorEffect {
            result: quiet(result),
            errno: Some(0x22),
        },
        Path::Domain { copy_x } => LibmErrorEffect {
            result: quiet(if copy_x { quiet(x) } else { result }),
            errno: Some(0x21),
        },
        Path::Silent => LibmErrorEffect {
            result: quiet(result),
            errno: None,
        },
    }
}

