const STACK_BASE: u32 = 0x3000_0000;
const STACK_SIZE: usize = 0x200;
/// Entry ESP: `0x977A10` aligns ESP to 16 before storing x, so `[esp+4]` is
/// 16-byte aligned at `0x977A29`.
const ENTRY_ESP: u32 = STACK_BASE + 0x10c;

struct Cpu {
    x: [[u64; 2]; 8],
    r: [u32; 8],
    stack: [u8; STACK_SIZE],
    zf: bool,
    sf: bool,
    cf: bool,
    of: bool,
    st0: Option<u64>,
    error: Option<u32>,
    errno: Option<u32>,
    fault: Option<u32>,
}

fn f(bits: u64) -> f64 {
    f64::from_bits(bits)
}
fn b(value: f64) -> u64 {
    value.to_bits()
}
fn is_nan(bits: u64) -> bool {
    bits & 0x7fff_ffff_ffff_ffff > 0x7ff0_0000_0000_0000
}
/// Signalling NaN -> quiet NaN (x87 `fld qword`, SSE NaN propagation).
fn quiet(bits: u64) -> u64 {
    if is_nan(bits) {
        bits | 0x0008_0000_0000_0000
    } else {
        bits
    }
}
const DEFAULT_NAN: u64 = 0xfff8_0000_0000_0000;
fn sse(a: u64, s: u64, op: fn(f64, f64) -> f64) -> u64 {
    if is_nan(a) {
        return quiet(a);
    }
    if is_nan(s) {
        return quiet(s);
    }
    let r = op(f(a), f(s));
    if r.is_nan() { DEFAULT_NAN } else { b(r) }
}
fn add(a: u64, s: u64) -> u64 {
    sse(a, s, |x, y| x + y)
}
fn sub(a: u64, s: u64) -> u64 {
    sse(a, s, |x, y| x - y)
}
fn mul(a: u64, s: u64) -> u64 {
    sse(a, s, |x, y| x * y)
}
#[allow(dead_code)]
fn div(a: u64, s: u64) -> u64 {
    sse(a, s, |x, y| x / y)
}
fn dwords(v: [u64; 2]) -> [u32; 4] {
    [
        v[0] as u32,
        (v[0] >> 32) as u32,
        v[1] as u32,
        (v[1] >> 32) as u32,
    ]
}
fn from_dwords(d: [u32; 4]) -> [u64; 2] {
    [
        u64::from(d[0]) | (u64::from(d[1]) << 32),
        u64::from(d[2]) | (u64::from(d[3]) << 32),
    ]
}
#[allow(dead_code)]
fn psubd(a: [u64; 2], s: [u64; 2]) -> [u64; 2] {
    let (a, s) = (dwords(a), dwords(s));
    from_dwords([0, 1, 2, 3].map(|i| a[i].wrapping_sub(s[i])))
}
#[allow(dead_code)]
fn pcmpeqd(a: [u64; 2], s: [u64; 2]) -> [u64; 2] {
    let (a, s) = (dwords(a), dwords(s));
    from_dwords([0, 1, 2, 3].map(|i| if a[i] == s[i] { u32::MAX } else { 0 }))
}
#[allow(dead_code)]
fn pshufd(s: [u64; 2], imm: i64) -> [u64; 2] {
    let d = dwords(s);
    let imm = imm as u32;
    from_dwords([0, 1, 2, 3].map(|i| d[((imm >> (2 * i)) & 3) as usize]))
}
#[allow(dead_code)]
fn psllq_var(v: [u64; 2], n: u64) -> [u64; 2] {
    if n > 63 {
        [0, 0]
    } else {
        [v[0] << n, v[1] << n]
    }
}
#[allow(dead_code)]
fn psrlq_var(v: [u64; 2], n: u64) -> [u64; 2] {
    if n > 63 {
        [0, 0]
    } else {
        [v[0] >> n, v[1] >> n]
    }
}
#[allow(dead_code)]
fn pmaxsw(a: [u64; 2], s: [u64; 2]) -> [u64; 2] {
    let mut out = [0u64; 2];
    for lane in 0..2 {
        for w in 0..4 {
            let x = ((a[lane] >> (16 * w)) & 0xffff) as u16 as i16;
            let y = ((s[lane] >> (16 * w)) & 0xffff) as u16 as i16;
            out[lane] |= u64::from(x.max(y) as u16) << (16 * w);
        }
    }
    out
}
#[allow(dead_code)]
fn pmovmskb(a: [u64; 2]) -> u32 {
    let mut mask = 0u32;
    for lane in 0..2 {
        for byte in 0..8 {
            if (a[lane] >> (8 * byte + 7)) & 1 != 0 {
                mask |= 1 << (lane * 8 + byte);
            }
        }
    }
    mask
}
/// `cvtsd2si` under MXCSR round-to-nearest-even; NaN/out of range give the
/// integer indefinite `0x80000000`.
#[allow(dead_code)]
fn cvtsd2si(v: f64) -> u32 {
    if v.is_nan() {
        return 0x8000_0000;
    }
    let r = v.round_ties_even();
    if r < -2147483648.0 || r > 2147483647.0 {
        0x8000_0000
    } else {
        (r as i32) as u32
    }
}

