#[cfg(test)]
mod native_fixtures {
    use super::*;

    const FIXTURES: &str =
        include_str!("../../../research/phase8-combat/native-crt-pow-fixtures.json");

    fn hex(v: &serde_json::Value) -> u64 {
        u64::from_str_radix(v.as_str().expect("hex"), 16).expect("hex")
    }
    fn opt(v: &serde_json::Value) -> Option<u32> {
        v.as_u64().map(|c| c as u32)
    }

    #[test]
    fn pow_matches_native_sse2_body_and_cipow() {
        let doc: serde_json::Value = serde_json::from_str(FIXTURES).expect("fixture");
        let (mut exact, mut nan_only) = (0, 0);
        for row in doc["cases"].as_array().expect("cases") {
            let (x, y, bits) = (hex(&row[1]), hex(&row[2]), hex(&row[3]));
            let out = match row[0].as_str() {
                Some("body") => pow_sse2_bits(x, y),
                Some("cipow") => ci_pow(f(x), f(y), CrtEnvironment::SSE2_DOUBLE53),
                other => panic!("entry {other:?}"),
            }
            .expect("modelled");
            let case = format!("{} x={x:016x} y={y:016x}", row[0]);
            assert_eq!(out.libm_error, opt(&row[4]), "{case}");
            assert_eq!(out.errno, opt(&row[5]), "{case}");
            if row[6].as_bool().expect("nan2") {
                // Unicorn picks between two distinct NaN operands with the x87
                // rule; only NaN-ness and quietness are ground truth.
                assert!(
                    is_nan(bits) && is_nan(out.bits) && out.bits == quiet(out.bits),
                    "{case}"
                );
                nan_only += 1;
            } else {
                assert_eq!(out.bits, bits, "{case}: got {:016x}", out.bits);
                exact += 1;
            }
        }
        assert!(exact > 11_000 && nan_only < 32, "{exact} {nan_only}");
        let corrected = doc["cases"]
            .as_array()
            .expect("cases")
            .iter()
            .filter(|r| r[7] == true)
            .count();
        assert!(corrected < 1500, "{corrected}");
    }

    #[test]
    fn libm_error_support_matches_native() {
        let doc: serde_json::Value = serde_json::from_str(FIXTURES).expect("fixture");
        let rows = doc["libm_cases"].as_array().expect("libm");
        assert!(rows.len() > 500);
        for row in rows {
            let code = row[0].as_i64().expect("code") as i32;
            let effect = libm_error_support(hex(&row[1]), hex(&row[2]), hex(&row[3]), code);
            assert_eq!(effect.result, hex(&row[4]), "code {code:#x}");
            assert_eq!(effect.errno, opt(&row[5]), "code {code:#x}");
        }
    }

    #[test]
    fn store_binary64_rounds_like_fstp_qword() {
        use crate::{Binary, Precision};
        for bits in [
            0u64,
            1 << 63,
            1,
            0x000f_ffff_ffff_ffff,
            0x0010_0000_0000_0000,
            0x3ff0_0000_0000_0001,
            0x7fef_ffff_ffff_ffff,
            0xc009_21fb_5444_2d18,
        ] {
            assert_eq!(
                store_binary64(&Binary::from_f64_bits(bits).unwrap()).unwrap(),
                bits
            );
        }
        // 1 + 2^-53 ties to even (1.0); 1 + 2^-53 + 2^-63 rounds up.
        let one = Binary::from_i32(1);
        let half_ulp = Binary::from_f64_bits(0x3ca0_0000_0000_0000).unwrap();
        let tie = one.add(&half_ulp, Precision::Extended64).unwrap();
        assert_eq!(store_binary64(&tie).unwrap(), 0x3ff0_0000_0000_0000);
        let above = tie
            .add(
                &Binary::from_f64_bits(0x3c00_0000_0000_0000).unwrap(),
                Precision::Extended64,
            )
            .unwrap();
        assert_eq!(store_binary64(&above).unwrap(), 0x3ff0_0000_0000_0001);
        // Largest finite + half ulp overflows; a subnormal tie rounds to even.
        let max = Binary::from_f64_bits(0x7fef_ffff_ffff_ffff).unwrap();
        let big = max
            .add(
                &Binary::from_f64_bits(0x7c90_0000_0000_0000).unwrap(),
                Precision::Extended64,
            )
            .unwrap();
        assert_eq!(store_binary64(&big), Err(CrtPowError::Binary64Overflow));
        let tiny = Binary::from_f64_bits(1).unwrap();
        let three_halves = tiny
            .add(
                &tiny
                    .mul(
                        &Binary::from_f64_bits(0x3fe0_0000_0000_0000).unwrap(),
                        Precision::Extended64,
                    )
                    .unwrap(),
                Precision::Extended64,
            )
            .unwrap();
        assert_eq!(store_binary64(&three_halves).unwrap(), 2);
    }

    #[test]
    fn dispatch_matches_native() {
        let doc: serde_json::Value = serde_json::from_str(FIXTURES).expect("fixture");
        for row in doc["dispatch_cases"].as_array().expect("dispatch") {
            let env = CrtEnvironment {
                sse2_available: row["sse2_flag"].as_u64() != Some(0),
                mxcsr: row["mxcsr"].as_u64().expect("mxcsr") as u32,
                x87_control: row["x87_control"].as_u64().expect("cw") as u16,
            };
            let expected = if row["path"] == "Sse2" {
                PowPath::Sse2
            } else {
                PowPath::X87
            };
            assert_eq!(select_path(env), expected, "{env:?}");
            let result = ci_pow(2.0, 0.5, env);
            match expected {
                PowPath::X87 => assert_eq!(result, Err(CrtPowError::X87PathUnsupported)),
                PowPath::Sse2 if env.mxcsr & 0xffc0 == 0x1f80 => assert!(result.is_ok()),
                PowPath::Sse2 => assert_eq!(result, Err(CrtPowError::UnsupportedMxcsr(env.mxcsr))),
            }
        }
    }
}
